#!/usr/bin/env bash
# Room migration safety net: the exported schema JSON of the current @Database version must exist in the repository
# (core/database/schemas/<AppDatabase FQCN>/<version>.json). Without the file a version bump cannot be migrated or
# migration-tested (MigrationTestHelper reads those files), and the build would regenerate it silently.
#
# The version is `AppDatabase.VERSION`, the constant the @Database annotation uses; every earlier version that
# shipped keeps its file too (they are the "from" side of a migration test). The files are generated by the build
# (`./gradlew :core:database:kspDebugKotlin`) and must be committed with the change that bumps the version.
#
# Usage: check-room-schemas.sh [database-dir]   (the argument exists for scripts/test-gates.sh)
set -euo pipefail

cd "$(dirname "$0")/.."

root="${1:-core/database}"
source_file="$root/src/main/kotlin/com/aedst/core/database/AppDatabase.kt"
schema_dir="$root/schemas/com.aedst.core.database.AppDatabase"

version=$(grep -oE 'const val VERSION = [0-9]+' "$source_file" | grep -oE '[0-9]+$' || true)
if [ -z "$version" ]; then
  echo "::error::Cannot read 'const val VERSION = N' from $source_file (the @Database version must be that constant)."
  exit 1
fi

status=0
if [ ! -s "$schema_dir/$version.json" ]; then
  echo "::error::Room schema $schema_dir/$version.json is missing for @Database version $version. Build :core:database and commit the generated file."
  status=1
fi

# Every version below the current one must still have its schema (migration tests start from them).
for ((v = 1; v < version; v++)); do
  if [ ! -s "$schema_dir/$v.json" ]; then
    echo "::error::Room schema $schema_dir/$v.json is missing; a shipped version's schema must be kept."
    status=1
  fi
done

# Schemas of a previous package name (the template's old com.yourname.myapp) are stale leftovers.
stale=$(find "$root/schemas" -mindepth 1 -maxdepth 1 -type d ! -name 'com.aedst.core.database.AppDatabase' 2>/dev/null || true)
if [ -n "$stale" ]; then
  echo "::error::Stale Room schema directories (not the current AppDatabase): $stale"
  status=1
fi

[ "$status" -eq 0 ] && echo "OK: Room schema for @Database version $version exists."
exit "$status"
